<script setup>
import {computed,ref,watch,nextTick,onMounted} from 'vue'
import Icon from './Icon.vue'
import {call} from './service'
import {youtubeVideoId} from './marketplace'
import DiscoveryInterests from './DiscoveryInterests.vue'
import {rankDiscovery} from './discoveryRanking'
import HelpTip from './HelpTip.vue'
const props=defineProps({data:Object,member:Object,initialClass:String,initialProvider:String})
const emit=defineEmits(['refresh','notify','setup','opened'])
const teaser=ref(false),sort=ref('Suggested')
const query=ref(''),type=ref('All'),country=ref('All'),selected=ref(null),classroom=ref(null),view=ref('Discover'),busy=ref(false),watching=ref(false)
const ranked=computed(()=>rankDiscovery(props.data.providers,props.data.classes,props.data.interests,[...(props.data.engaged_keywords||[]),...props.data.enrollments.flatMap(e=>props.data.classes.find(c=>c.name===e.classroom)?.keywords||[])],sort.value))
const providers=computed(()=>ranked.value.filter(p=>(type.value==='All'||p.type===type.value)&&(country.value==='All'||p.country===country.value)&&`${p.title} ${p.username} ${p.code} ${p.subjects} ${p.education_system} ${(p.keywords||[]).join(' ')}`.toLowerCase().includes(query.value.toLowerCase())))
const classes=computed(()=>props.data.classes.filter(c=>c.provider===selected.value?.name).slice().sort((a,b)=>(b.active_learners_30d||0)-(a.active_learners_30d||0)))
const enrollment=computed(()=>props.data.enrollments.find(e=>e.classroom===classroom.value?.name))
const amount=c=>new Intl.NumberFormat('en',{style:'currency',currency:c.currency,maximumFractionDigits:0}).format(c.fee)
const provider=c=>props.data.providers.find(p=>p.name===c.provider)
async function openClass(c){classroom.value=c;watching.value=false;await nextTick();document.querySelector('.selected-market-class')?.scrollIntoView({behavior:'smooth',block:'start'})}
watch(selected,()=>teaser.value=false)
onMounted(()=>{if(props.initialProvider){selected.value=props.data.providers.find(p=>p.name===props.initialProvider);emit('opened')}if(props.initialClass){const c=props.data.classes.find(c=>c.name===props.initialClass);if(c){view.value='My enrollments';openClass(c)}emit('opened')}})
async function enroll(c){busy.value=true;try{await call('marketplace_enroll',{classroom:c.name});emit('refresh');openClass(c);emit('notify','Demo enrollment created. This provider has its own student ID and payment access.')}catch(e){emit('notify',e.message)}finally{busy.value=false}}
async function settle(){try{await call('marketplace_demo_payment',{classroom:classroom.value.name});emit('refresh');emit('notify','Demo installment settled. No real money was collected.')}catch(e){emit('notify',e.message)}}
watch(()=>props.member.name,()=>{selected.value=null;classroom.value=null})
</script>
<template><div class="page-heading"><div><div class="eyebrow">GOOD TEACHING HAS NO BORDERS</div><h1>Find your next place to grow.</h1><p>Discover institutes and independent teachers. Choose the education that fits you.</p></div><button class="button subtle" @click="$emit('setup')"><Icon name="GraduationCap" :size="17"/>Teach on Sisu</button></div><section class="discovery-hero"><div><span class="eyebrow">YOUR NEXT CHAPTER STARTS WITH A CONNECTION</span><h2>One curious mind.<br>A world of possibilities.</h2><p>Search by teacher, academy, username, subject or education system.</p></div><div class="world-art" aria-hidden="true"><Icon name="Globe2" :size="140"/><span>العربية · English · සිංහල · தமிழ்</span></div></section><div class="toolbar"><div class="tabs"><button v-for="v in ['Discover','My enrollments']" :class="{selected:view===v}" @click="view=v;selected=null;classroom=null">{{v}} <span v-if="v==='My enrollments'">({{data.enrollments.length}})</span></button></div><label class="search"><Icon name="Search" :size="17"/><input v-model="query" aria-label="Search institutes and teachers" placeholder="Institute, teacher, subject or @username"></label></div>
<template v-if="view==='Discover'"><DiscoveryInterests v-if="member.role==='Student'&&!selected" :interests="data.interests" @saved="$emit('refresh')"/><div class="directory-filters"><label>Provider type<select v-model="type"><option>All</option><option>Institute</option><option>Independent teacher</option></select></label><label>Country<select v-model="country"><option>All</option><option v-for="c in [...new Set(data.providers.map(p=>p.country))]">{{c}}</option></select></label><label>Sort by<select v-model="sort"><option>Suggested</option><option>Most active</option></select></label><span>{{providers.length}} fictional demo profiles · activity is simulated</span></div><div v-if="!selected" class="provider-grid"><article v-for="p in providers" :key="p.name" class="provider-card"><div class="provider-banner" :style="{background:p.color}"><img v-if="p.cover_image" :src="p.cover_image" alt="" loading="lazy"><span class="badge white">{{p.type}}</span><span class="provider-glyph">✳</span></div><div class="provider-copy"><img v-if="p.profile_image" class="provider-avatar" :src="p.profile_image" alt=""><span v-else class="provider-avatar" :style="{background:p.color}">{{p.symbol}}</span><small class="provider-handle">@{{p.username}} · {{p.code}}</small><h2>{{p.title}}</h2><p class="provider-location"><Icon name="MapPin" :size="14"/>{{p.city}} · {{p.country}}</p><span class="badge violet">{{p.education_system}}</span><p class="provider-bio">{{p.bio}}</p><p class="recommendation-reason">✦ {{p.discovery.reason}} · {{p.discovery.activity}} active class memberships / 30 days</p><div class="provider-keywords"><span v-for="tag in p.keywords">{{tag}}</span></div><div class="inline spread"><small>{{p.languages}}</small><button class="button primary small" @click="selected=p">{{p.type==='Institute'?'View institute':'View teacher'}} <Icon name="ArrowRight" :size="15"/></button></div></div></article></div><section v-if="!providers.length" class="panel empty-state"><Icon name="Search"/><h2>No matching profiles yet.</h2><p>Try another country, subject or username.</p></section>
<section v-if="selected" class="provider-profile"><button class="text-button" @click="selected=null;classroom=null"><Icon name="ChevronLeft" :size="16"/>Back to discovery</button><div class="profile-banner" :style="{background:selected.color}"><img v-if="selected.cover_image" :src="selected.cover_image" alt="" loading="lazy"><span class="eyebrow">{{selected.type.toUpperCase()}} · {{selected.country}}</span><h2>{{selected.title}}</h2><p>@{{selected.username}} · {{selected.code}} · {{selected.city}}</p><span class="badge white">{{selected.education_system}}</span></div><div class="provider-profile-grid"><section class="panel"><h2>{{selected.type==='Institute'?'About the academy':'Meet your teacher'}}</h2><p>{{selected.bio}}</p><dl><dt>Subjects</dt><dd>{{selected.subjects||'To be added'}}</dd><dt>Local time zone & currency</dt><dd>{{selected.timezone||'Not specified'}} · {{selected.currency||'See course fee'}}</dd><dt>Teaching languages</dt><dd>{{selected.languages}}</dd><template v-if="selected.type==='Independent teacher'"><dt>Qualifications</dt><dd>{{selected.qualifications}}</dd><dt>Teaching experience</dt><dd>{{selected.experience||0}} years</dd><dt>Teaching approach</dt><dd>{{selected.teaching_style||'Ask the teacher about their approach.'}}</dd><dt>Availability & time zone</dt><dd>{{selected.availability||'See each class schedule.'}}</dd></template></dl><a v-if="selected.website" class="text-button" :href="selected.website" target="_blank" rel="noopener noreferrer">Teacher website <Icon name="ArrowUpRight" :size="16"/></a><div v-if="selected.youtube_url" class="teacher-teaser"><h3>Meet {{selected.title}} on video <HelpTip text="This is the teacher’s teaser video. Public or unlisted videos play when the owner allows embedding. Private YouTube videos require an invited Google account."/></h3><button class="button primary" @click="teaser=!teaser"><Icon name="Play" :size="16"/>{{teaser?'Close teaser':'Watch teacher introduction'}}</button><p v-if="selected.video_visibility==='Private'" class="field-help">Private YouTube video · an invitation from the owner may be required.</p><iframe v-if="teaser&&youtubeVideoId(selected.youtube_url)" :src="'https://www.youtube.com/embed/'+youtubeVideoId(selected.youtube_url)" title="Teacher introduction video" referrerpolicy="strict-origin-when-cross-origin" allow="encrypted-media; picture-in-picture" allowfullscreen></iframe></div><div v-if="Object.values(selected.socials||{}).some(Boolean)" class="profile-socials"><h3>Connect with {{selected.title}}</h3><a v-for="(url,network) in selected.socials" v-show="url" :href="url" target="_blank" rel="noopener noreferrer" class="button subtle small">{{network}} <Icon name="ArrowUpRight" :size="14"/></a></div><p class="field-help">This is a fictional profile. Credentials and experience shown here are demonstration data, not verified claims.</p></section><section><div class="section-heading"><h2>Find your class</h2><span class="count-pill">{{classes.length}}</span></div><article v-for="c in classes" :key="c.name" class="panel discover-class"><div class="inline spread"><span class="badge violet">{{c.level}}</span><small>{{c.mode}} · {{c.medium}}</small></div><h3 :class="{handwritten:/[\u0D80-\u0DFF]/.test(c.title)}">{{c.title}}</h3><span v-if="c.duration_months" class="badge mint">{{c.duration_months}} month course</span><p>{{c.teacher}} · {{c.active_learners_30d||0}} active learners / 30 days · demo</p><div class="inline spread"><strong>{{amount(c)}} <small>/ month</small></strong><button class="button primary small" :disabled="busy||member.role!=='Student'" @click="data.enrollments.some(e=>e.classroom===c.name)?openClass(c):enroll(c)">{{data.enrollments.some(e=>e.classroom===c.name)?'Open selected class':'Enroll'}} <Icon name="ArrowRight" :size="15"/></button></div></article><p v-if="member.role!=='Student'" class="field-help">Switch the preview to Student to enroll in a class.</p><section v-if="!classes.length" class="panel empty-state"><Icon name="BookOpen"/><p>This new provider has not published classes yet.</p></section></section></div></section></template>
<template v-else><div class="provider-grid"><article v-for="e in data.enrollments" :key="e.name" class="panel discover-class"><span class="badge" :class="e.status==='Paid'?'green':'amber'">{{e.status==='Paid'?'Ready to learn':'Payment required'}}</span><h2>{{data.classes.find(c=>c.name===e.classroom)?.title}}</h2><p>{{data.providers.find(p=>p.name===e.provider)?.title}}</p><small>Your provider ID · {{e.student_id}}</small><button class="button primary" @click="openClass(data.classes.find(c=>c.name===e.classroom))">Open selected class <Icon name="ArrowRight" :size="16"/></button></article></div><section v-if="!data.enrollments.length" class="panel empty-state"><Icon name="BookOpen"/><h2>Your next chapter is waiting.</h2><p>Explore a teacher or institute, choose a class, then select Enroll.</p><button class="button primary" @click="view='Discover'">Discover classes</button></section></template>
<section v-if="classroom" class="panel selected-market-class" aria-live="polite"><div class="section-heading"><div><span class="eyebrow">YOUR SELECTED CLASSROOM</span><h2>{{classroom.title}}</h2><p>{{provider(classroom)?.title}} · {{classroom.teacher}}</p></div><button class="icon-button" aria-label="Close selected class" @click="classroom=null;watching=false"><Icon name="X"/></button></div><div class="selected-class-facts"><span><small>Student ID at this provider</small><b>{{enrollment?.student_id}}</b></span><span><small>Monthly installment</small><b>{{amount(classroom)}}</b></span><span><small>Language</small><b>{{classroom.medium}}</b></span></div><p>{{classroom.description}}</p><template v-if="enrollment?.status!=='Paid'"><div class="form-note"><Icon name="LockKeyhole"/><span>Enrollment saved. Settle the first installment to unlock recordings and learning materials.</span></div><button class="button primary" @click="settle">Simulate payment & unlock</button><p class="field-help">No money is collected. payments.lk supports LKR; non-LKR currencies are illustrative listings and require a compatible payment provider before launch.</p></template><template v-else><span class="badge green">Demo receipt · {{enrollment.receipt}}</span><button class="button primary" @click="watching=!watching"><Icon name="Play" :size="17"/>{{watching?'Close player':'Watch sample recording'}}</button><iframe v-if="watching" :src="'https://www.youtube.com/embed/'+classroom.youtube_id" title="Selected classroom sample video" referrerpolicy="strict-origin-when-cross-origin" allow="encrypted-media; picture-in-picture" allowfullscreen></iframe></template></section>
</template>
